-- =========================================================================
-- EcoReporte GT — Límites municipales (Fase 4: municipalidad por ubicación)
--
-- Agrega a municipalidad la columna limite (MultiPolygon, WGS84) con índice GiST
-- y carga los 17 municipios del departamento de Guatemala.
--   · La Municipalidad de Guatemala (id 1) conserva su id, sigue activa y recibe su límite.
--   · Las otras 16 se registran con estado_activo = FALSE (aún no adoptan la plataforma);
--     el administrador las activa desde Catálogos.
--
-- Fuente de los límites: geoBoundaries (gbOpen), Guatemala, nivel ADM2 (municipios),
--   https://www.geoboundaries.org/ — release 9469f09, año representado 2021.
--   Origen: CONRED / OCHA (data.humdata.org). Licencia: CC BY 3.0 IGO.
--   Selección: municipios ADM2 cuyo punto interior cae dentro del departamento
--   de Guatemala (ADM1). Coordenadas redondeadas a 7 decimales (~1 cm).
--
-- Requiere PostGIS (ver 01_esquema.sql). Ejecutar después de 01 a 04.
-- Es idempotente: se puede volver a correr (no duplica municipalidades y
-- actualiza los límites), y no cambia el estado_activo de las existentes.
-- =========================================================================

-- Los nombres llevan tildes: evita que psql en Windows los lea con otra codificación.
SET client_encoding = 'UTF8';

BEGIN;

ALTER TABLE municipalidad
    ADD COLUMN IF NOT EXISTS limite geometry(MultiPolygon, 4326);

CREATE INDEX IF NOT EXISTS idx_municipalidad_limite
    ON municipalidad USING GIST (limite);

CREATE TEMP TABLE limites_guatemala (nombre VARCHAR(100), limite geometry(MultiPolygon, 4326))
    ON COMMIT DROP;

INSERT INTO limites_guatemala (nombre, limite) VALUES
