-- Registra las municipalidades que aún no existen (inactivas por defecto).
-- La de Guatemala ya existe como id 1 (02_datos_iniciales.sql), así que no se duplica.
INSERT INTO municipalidad (nombre, departamento, estado_activo)
SELECT l.nombre, 'Guatemala', FALSE
FROM limites_guatemala l
WHERE NOT EXISTS (SELECT 1 FROM municipalidad m WHERE m.nombre = l.nombre);

-- Asigna (o actualiza) el límite de cada municipalidad.
UPDATE municipalidad m
SET limite = l.limite
FROM limites_guatemala l
WHERE m.nombre = l.nombre;

COMMIT;
